This file introduces a full custom `useMutation` mock implementation. The exact same mock block is duplicated in multiple File IQ unit tests; extracting it into a shared test helper would reduce duplication and make it easier to keep the mock in sync with the real `useMutation` contract.
```suggestion
type MockMutationOptions = {
  mutationFn: (variables: unknown) => Promise<unknown>;
  onSuccess?: (data: unknown, variables: unknown) => void | Promise<void>;
  onError?: (error: unknown, variables: unknown) => void | Promise<void>;
};

const createMockUseMutation = (React: typeof import('react')) =>
  (options: MockMutationOptions) => {
    const [isPending, setIsPending] = React.useState(false);
    const [error, setError] = React.useState<unknown>(null);

    return {
      isPending,
      error,
      mutate: async (variables: unknown) => {
        setIsPending(true);
        setError(null);
        try {
          const data = await options.mutationFn(variables);
          await options.onSuccess?.(data, variables);
        } catch (mutationError) {
          setError(mutationError);
          await options.onError?.(mutationError, variables);
        } finally {
          setIsPending(false);
        }
      },
    };
  };

vi.mock('@hooks/useMutation', async () => {
  const React = await import('react');
  return {
    useMutation: createMockUseMutation(React),
