The MSW handler request body typing and parsing ignores required fields like `enabled` (present in real requests). Tightening the expected shape (and optionally returning a 400 for missing/invalid fields) helps these handlers act as contract checks and prevents tests from accidentally passing with malformed requests.
```suggestion
type FileIQAppliancesPatchBody = {
  enabled: boolean;
  file_iq_ids: string[];
};

type FileIQEdgesPatchBody = {
  enabled: boolean;
  edge_ids: string[];
};

const isStringArray = (value: unknown): value is string[] =>
  Array.isArray(value) && value.every((item) => typeof item === 'string');

const isFileIQAppliancesPatchBody = (value: unknown): value is FileIQAppliancesPatchBody => {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  const body = value as Record<string, unknown>;
  return typeof body.enabled === 'boolean' && isStringArray(body.file_iq_ids);
};

const isFileIQEdgesPatchBody = (value: unknown): value is FileIQEdgesPatchBody => {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  const body = value as Record<string, unknown>;
  return typeof body.enabled === 'boolean' && isStringArray(body.edge_ids);
};

export const handlers = [
  http.patch(BffRoute('/fiq_appliances'), async ({ request }) => {
    const body = (await request.json()) as unknown;

    if (!isFileIQAppliancesPatchBody(body)) {
      return HttpResponse.json({ message: 'Invalid request body' }, { status: 400 });
    }

    return HttpResponse.json(getFileIQUpdateAppliancesResponseDto(body.file_iq_ids), { status: 200 });
  }),

  http.patch(BffRoute('/fiq_edges'), async ({ request }) => {
    const body = (await request.json()) as unknown;

    if (!isFileIQEdgesPatchBody(body)) {
      return HttpResponse.json({ message: 'Invalid request body' }, { status: 400 });
    }

    return HttpResponse.json(getFileIQUpdateEdgesResponseDto(body.edge_ids), { status: 200 });
