This MSW-based contract test largely duplicates the MSW-based assertions in `frontend/tests/e2e/webbff/queries/file-iq.test.ts`. Consider keeping a single source of truth (unit or e2e) to avoid duplicated coverage and maintenance overhead.
```suggestion
describe('File IQ query smoke tests', () => {
  it('Fetches File IQ appliances through MSW', async () => {
    const appliances = await fetchFileIQAppliances();

    expect(appliances.length).toBeGreaterThan(0);
    expect(appliances[0]).toEqual(
      expect.objectContaining({
        fileIqName: expect.any(String),
        fileIqId: expect.any(String),
      }),
    );
  });

  it('Fetches File IQ edges through MSW', async () => {
    const edges = await fetchFileIQEdges();

    expect(edges.length).toBeGreaterThan(0);
    expect(edges[0]).toEqual(
      expect.objectContaining({
        edgeName: expect.any(String),
        edgeId: expect.any(String),
      }),
    );
